+        llvm::isa<TF::Qint8Type>(op.getDstT())) {
+      output_type = rewriter.getI8Type();
+    } else if (llvm::isa<TF::Qint32Type>(op.getSrcT()) ||
+               llvm::isa<TF::Qint32Type>(op.getDstT())) {
+      output_type = rewriter.getI32Type();
