+          if (node->input(2).compare("^add_1")) found++;
+        } else if (node->input(1).compare("^add_1")) {
+          if (node->input(2).compare("^add_0")) found++;
+        }
+      }
+    }
+    EXPECT_EQ(found, 1);
+  }
+};
